// Package gentest holds Go types generated by encoding/gocode from the
// exemplar lineages and from the shapes lineage in shapes.cue, each lineage in
// a directory named for it, as LineageTypes lays out its versions:
// expand/v0_2/types.go. The generated files are goldens: encoding/gocode's
// tests check they are what the generator produces, and this package's tests
// check they compile and are assignable from their schemas.
package gentest

import (
	"embed"
	"testing/fstest"

	"cuelang.org/go/cue"
	"github.com/sdboyer/thema"
	"github.com/sdboyer/thema/internal/util"
	tload "github.com/sdboyer/thema/load"
)

//go:embed shapes.cue
var shapesFS embed.FS

// ShapesLineage returns the shapes lineage declared in shapes.cue.
func ShapesLineage(rt *thema.Runtime) (thema.Lineage, error) {
	src, err := shapesFS.ReadFile("shapes.cue")
	if err != nil {
		return nil, err
	}
	fsys := fstest.MapFS{
		"shapes.cue":         &fstest.MapFile{Data: src},
		"cue.mod/module.cue": &fstest.MapFile{Data: []byte(util.ModuleFile("github.com/sdboyer/thema/gentest"))},
	}
	inst, err := tload.InstanceWithThema(fsys, ".")
	if err != nil {
		return nil, err
	}
	v := rt.Context().BuildInstance(inst).LookupPath(cue.ParsePath("shapes"))
	return thema.BindLineage(v, rt)
}
